problems.reference_solution:
def format_receipt(items):
    """Return the receipt for (name, price) pairs, one 30-character line each, then the total."""
    lines = [_line(name, price) for name, price in items]
    lines.append(_line('Total', sum(price for _, price in items)))
    return '\n'.join(lines)


def _line(name, price):
    if len(name) > 20:
        name = name[:17] + '...'
    return f'{name:<20}{price:>10.2f}'

