problems.reference_solution:
import copy


def merge_settings(defaults, overrides):
    """Return a new dict: defaults with overrides applied, nested dicts merged."""
    result = copy.deepcopy(defaults)
    for key, value in overrides.items():
        if isinstance(result.get(key), dict) and isinstance(value, dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = copy.deepcopy(value)
    return result

problems.tests:
import copy

from solution import *


def test_example_1():
    """A nested dict is merged key by key."""
    assert merge_settings(
        {'ui': {'theme': 'light', 'size': 12}, 'beta': False}, {'ui': {'theme': 'dark'}}
    ) == {'ui': {'theme': 'dark', 'size': 12}, 'beta': False}


def test_example_2():
    """Lists and plain values are replaced."""
    assert merge_settings({'tags': ['a'], 'ui': {'size': 12}}, {'tags': ['b'], 'ui': 'plain'}) == {
        'tags': ['b'],
        'ui': 'plain',
    }


def test_value_replaced_by_dict():
    """A plain value replaced by a dict."""
    assert merge_settings({'ui': 'plain'}, {'ui': {'size': 9}}) == {'ui': {'size': 9}}


def test_empty():
    """Empty dicts on either side."""
    assert merge_settings({}, {}) == {}
    assert merge_settings({'a': {'b': 1}}, {}) == {'a': {'b': 1}}
    assert merge_settings({}, {'a': {'b': 1}}) == {'a': {'b': 1}}


def _sample():
    defaults = {'ui': {'theme': 'light', 'panels': {'left': True}}, 'tags': ['a'], 'n': 1}
    overrides = {'ui': {'panels': {'right': False}, 'fonts': ['mono']}, 'extra': {'x': [1]}}
    return defaults, overrides


def test_inputs_unchanged():
    """Merging changes neither input."""
    defaults, overrides = _sample()
    before = copy.deepcopy((defaults, overrides))
    merge_settings(defaults, overrides)
    assert (defaults, overrides) == before


def test_result_shares_nothing():
    """Changing the result at any depth leaves both inputs as they were."""
    defaults, overrides = _sample()
    before = copy.deepcopy((defaults, overrides))
    result = merge_settings(defaults, overrides)
    result['ui']['theme'] = 'dark'
    result['ui']['panels']['left'] = False
    result['ui']['panels']['right'] = True
    result['ui']['fonts'].append('serif')
    result['tags'].append('b')
    result['extra']['x'].append(2)
    assert (defaults, overrides) == before


def test_deep():
    """Dicts nested 20 levels deep."""
    def nest(depth, leaf):
        return leaf if depth == 0 else {'k': nest(depth - 1, leaf)}

    merged = merge_settings(nest(19, {'a': 1}), nest(19, {'b': 2}))
    assert merged == nest(19, {'a': 1, 'b': 2})

