    pass

problems.reference_solution:
def top_students(scores, k):
    """Return the k (name, average) pairs with the best averages, ties by name."""
    averages = {name: sum(marks) / len(marks) for name, marks in scores.items()}
    ranked = sorted(averages, key=lambda name: (-averages[name], name))
    return [(name, round(averages[name], 2)) for name in ranked[:k]]

