problems.reference_solution:
class ScoreError(ValueError):
    """A line of scores that can't be read."""


def read_scores(lines):
    """Return a dict of names to integer scores, raising ScoreError for a bad line."""
    scores = {}
    for number, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        name, colon, score = line.partition(':')
        name = name.strip()
        if not colon:
            raise ScoreError(f'line {number}: no colon')
        if not name:
            raise ScoreError(f'line {number}: no name')
        if name in scores:
            raise ScoreError(f'line {number}: {name} appears again')
        try:
            scores[name] = int(score)
        except ValueError as error:
            raise ScoreError(f'line {number}: {score.strip()!r} is not an integer') from error
    return scores

problems.tests:
from solution import *


def _error(lines):
    try:
        read_scores(lines)
    except ScoreError as error:
        return error
    raise AssertionError('no ScoreError was raised')


def test_example_1():
    """Spaces are ignored and blank lines skipped."""
    assert read_scores(['ann: 90', '', ' bob :7 ']) == {'ann': 90, 'bob': 7}


def test_example_2():
    """A score that is not a number names its line."""
    assert str(_error(['ann: 90', 'bob: ninety'])).startswith('line 2:')


def test_cause():
    """The error is raised from the ValueError of int."""
    error = _error(['bob: 9.5'])
    assert isinstance(error.__cause__, ValueError)
    assert not isinstance(error.__cause__, ScoreError)


def test_is_value_error():
    """ScoreError is still a ValueError."""
    assert isinstance(_error(['x']), ValueError)


def test_no_colon():
    """A line without a colon."""
    assert str(_error(['ann: 1', '   ', 'bob 2'])).startswith('line 3:')


def test_empty_name():
    """A line with nothing before the colon."""
    assert str(_error([' : 5'])).startswith('line 1:')


def test_repeated_name():
    """A name read twice."""
    assert str(_error(['ann: 1', 'bob: 2', ' ann : 3'])).startswith('line 3:')


def test_first_colon():
    """Only the first colon splits; the rest belongs to the score."""
    assert str(_error(['a: 1: 2'])).startswith('line 1:')


def test_signs_and_empty():
    """Negative scores are integers; no lines give an empty dict."""
    assert read_scores(['low: -3', 'high: +4']) == {'low': -3, 'high': 4}
    assert read_scores([]) == {}


def test_many():
    """Ten thousand lines."""
    lines = [f'p{i}: {i}' for i in range(10000)]
    assert read_scores(lines) == {f'p{i}': i for i in range(10000)}

